      "history": "كانت بالاط تاريخيًا مركز الجالية اليهودية السفاردية في إسطنبول، وينحدر كثير من سكانها من يهود رحّبت بهم الدولة العثمانية بعد طردهم من إسبانيا عام 1492. وحافظ الحيّ لعدة قرون على معابده اليهودية وهويته المجتمعية المميزة وثقافة حرفية وتجارية قوية. وغادر معظم سكانه اليهود على مدى القرن العشرين، خصوصًا بعد عام 1948، لكن المعابد اليهودية التاريخية ومنظر الحيّ الكثيف والملوّن ما زالا قائمين، وقد جذبا في السنوات الأخيرة موجة من الترميم والاهتمام المتجدد.",
