      "name": "حديقة يلدز",
      "summary": "حديقة كبيرة وتلالية مشجرة تطل على البوسفور، كانت يومًا الأراضي الخاصة لقصر يلدز.",
      "whatIsIt": "حديقة بلدية شاسعة ومشجرة تضم مروجًا وبحيرات صغيرة وأجنحة تاريخية، مع لمحات من البوسفور تظهر بين الأشجار.",
