      "summary": "أكبر جزر الأمراء، وتشتهر بقصورها الخشبية الفخمة التي تعود إلى القرن التاسع عشر، وتلالها المكسوة بغابات الصنوبر، وحظرها التام على السيارات الخاصة.",
